function floor(key,x,z,rotationY=0,name) {
  return api.place({
    assetId:api.asset(key), name,
    position:api.roomPoint(x,z,0),
    dimensions:dims[key], rotationY, role:roles[key]
  });
}
function wall(key,side,offset,bottom,inset=0.08) {
  const f = api.wallFrame(side,offset,bottom,inset);
  return api.place({
    assetId:api.asset(key), position:f.point,
    facing:{direction:f.inward}, dimensions:dims[key], role:roles[key]
  });
}
function supported(key,parentId,x=0,z=0) {
  return api.attach({
    assetId:api.asset(key), parentId, kind:"supported",
    offset:[x,z], dimensions:dims[key], role:roles[key]
  });
}
function overhead(x,z) {
  return api.place({
    assetId:api.asset("pendant"),
    position:api.ceilingPoint(x,z,dims.pendant[1],0.5),
    dimensions:dims.pendant, role:"functional"
  });
}
function toward(key,x,z,targetX,targetZ,name) {
  return floor(key,x,z,Math.atan2(targetX-x,targetZ-z),name);
}

