  const openings = Array.isArray(api.room.openings) ? api.room.openings.slice() : [];
  const doors = openings.filter(o => o.kind === "door");
  if (!doors.length) {
    api.opening({id: "main-entry", kind: "door", wall: "south", offset: 0, bottom: 0, width: 2.8, height: 3.1});
    api.opening({id: "ballroom-passage", kind: "door", wall: "east", offset: 0, bottom: 0, width: 2.4, height: 3});
    doors.push({wall: "south", offset: 0, width: 2.8}, {wall: "east", offset: 0, width: 2.4});
    openings.push(...doors);
  }
  if (!openings.some(o => o.kind === "window" && o.wall === "south")) {
    for (const offset of [-9.6, -6.4, -3.2, 3.2, 6.4, 9.6]) {
      const obstructed = openings.some(o => o.wall === "south" &&
        Math.abs((o.offset || 0) - offset) < (o.width || 1.5) / 2 + 1.5);
      if (!obstructed) api.opening({
        id: "south-daylight-" + offset, kind: "window", wall: "south",
        offset, bottom: 0.45, width: 2.7, height: 3.05
      });
    }
  }
  const routes = [
    [[0, -6.6], [0, 6.9], 0.9],
    [[-10.6, 0], [10.6, 0], 0.85]
  ];
  const swingZones = [];
  for (const door of doors) {
    const frame = api.wallFrame(door.wall || "south", Number(door.offset) || 0, 0, 0.12);
    const center = api.room.position || [0, 0, 0];
    const p = frame.point;
    const inward = frame.inward;
    const component = (v, i, key) => Array.isArray(v) ? v[i] : v[key];
    const x = component(p, 0, "x") - component(center, 0, "x");
    const z = component(p, 2, "z") - component(center, 2, "z");
    const dx = component(inward, 0, "x");
    const dz = component(inward, 2, "z");
    const q = [x + dx * 2.1, z + dz * 2.1];
    routes.push([[x, z], q, Math.max(0.85, (door.width || 1.5) / 2)]);
    routes.push([q, [0, 0], 0.8]);
    swingZones.push([x, z, Math.max(1.8, (door.width || 1.5) * 0.75)]);
  }
  function distanceSegment(x, z, a, b) {
    const dx = b[0] - a[0], dz = b[1] - a[1];
    const t = Math.max(0, Math.min(1, ((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz || 1)));
    return Math.hypot(x-a[0]-t*dx, z-a[1]-t*dz);
  }
  function circulation(x, z) {
    let d = Infinity;
    for (const [a, b, r] of routes) d = Math.min(d, distanceSegment(x,z,a,b)-r);
    for (const [a,b,r] of swingZones) d = Math.min(d, Math.hypot(x-a,z-b)-r);
    return d;
  }
  const occupied = [];
  function clear(x,z,w,d) {
    if (Math.abs(x)+w/2 > 11.7 || Math.abs(z)+d/2 > 7.65) return false;
    for (let u=-w/2; u<=w/2+0.01; u+=w/Math.ceil(w/0.3)) {
      for (let v=-d/2; v<=d/2+0.01; v+=d/Math.ceil(d/0.3)) {
        if (circulation(x+u,z+v)<0.18) return false;
      }
    }
    return !occupied.some(o => Math.abs(x-o.x)<(w+o.w)/2+0.25 && Math.abs(z-o.z)<(d+o.d)/2+0.25);
  }
  function zone(w,d,tx,tz,daylight) {
    let best = null, score = -Infinity;
    for (let x=-11.5+w/2; x<=11.5-w/2; x+=0.35) {
      for (let z=-7.5+d/2; z<=7.5-d/2; z+=0.35) {
        if (!clear(x,z,w,d)) continue;
        const light = Math.exp(-(7.7-z)/5);
        const s = -Math.pow(x-tx,2)-Math.pow(z-tz,2)+daylight*light;
        if (s>score) { score=s; best={x,z,w,d}; }
      }
    }
    if (best) occupied.push(best);
    return best;
  }
  function put(key,x,z,rotation=0) {
