    put("taskchair",x+1.15,z-0.1);
    top("terminal",desk,-1.3,0);
    top("vase",desk,1.8,0);
    light(x,z+0.7);
  }
  const bar = zone(5.9,3.9,6.7,-4.6,0);
  if (bar) {
    const {x,z}=bar;
    put("barback",x,z-1.65);
    const counter=put("bar",x,z+0.2);
    for (const dx of [-1.85,-0.62,0.62,1.85]) put("stool",x+dx,z+1.5,Math.PI);
    top("espresso",counter,-1.6,0);
    top("water",counter,1.9,0);
    top("tray",counter,0.5,0);
    light(x-1.5,z+0.2);
    light(x+1.5,z+0.2);
  }
  const lounge=zone(6.3,4.1,-6.6,4.65,5);
  if (lounge) {
    const {x,z}=lounge;
    put("rug",x,z);
    put("sofa",x,z-1.25);
    const coffee=put("coffee",x,z);
    top("books",coffee,-0.4,0);
    top("vase",coffee,0.45,0);
    put("armchair",x-1.5,z+1.25,Math.PI-0.22);
    put("armchair",x+1.5,z+1.25,Math.PI+0.22);
    const side=put("sidetable",x+2.5,z-0.9);
    top("tray",side);
    put("lamp",x-2.6,z-1.2);
    light(x,z);
  }
  for (let i=0;i<4;i++) {
    const dining=zone(2.4,3.05,i%2===0?4.2:8.6,i<2?3:6,7);
    if (!dining) continue;
    const {x,z}=dining;
    const table=put("dining",x,z);
    put("banquette",x,z-1.05);
    for (const dx of [-0.43,0.43]) put("dinechair",x+dx,z+1.02,Math.PI);
    for (const dx of [-0.43,0.43]) {
      top("setting",table,dx,-0.23);
      top("setting",table,dx,0.23);
    }
    top("vase",table);
    light(x,z);
  }
  const service=zone(1.8,0.8,10.5,2,0);
  if (service) {
    const cabinet=put("service",service.x,service.z);
    top("tray",cabinet,-0.35,0);
  }
  const sign=zone(0.7,0.6,1.7,6.5,0);
  if (sign) put("sign",sign.x,sign.z);
  for (const target of [[-10.7,6.6],[-10.7,-6.5],[10.6,-6.5],[10.5,6.6],[-9.9,2]]) {
    const p=zone(1.05,1.05,target[0],target[1],3);
    if (p) put("plant",p.x,p.z);
  }
}

