  const southOpenings = existing.filter(o => o.wall === "south").concat(entrances.filter(o => o.wall === "south"));
  let windowsPlaced = 0;
  for (const x of [-9.5, -5.65, 5.65, 9.5]) {
    if (southOpenings.some(o => Math.abs((o.offset || 0) - x) < (o.width || 2.4) / 2 + 1.7)) continue;
    const id = api.opening({ id: "south-daylight-" + windowsPlaced, kind: "window", wall: "south", offset: x, bottom: 0.45, width: 3.15, height: 3.15 });
    api.place({ assetId: api.asset("window"), roomOpeningId: id, dimensions: dims.window, role: "functional" });
    windowsPlaced++;
  }
  if (!windowsPlaced) {
    const win = existing.find(o => o.kind === "window");
    if (win) api.place({ assetId: api.asset("window"), roomOpeningId: win.id, dimensions: [win.width || 3.15, win.height || 3.15, 0.16], role: "functional" });
    else {
      const id = api.opening({ id: "south-clerestory", kind: "window", wall: "south", offset: 0, bottom: 3.35, width: 3, height: 0.45 });
      api.place({ assetId: api.asset("window"), roomOpeningId: id, dimensions: [3, 0.45, 0.16], role: "functional" });
    }
  }

  // Shape grammar: reception and beverage service anchor the north;
  // a conversational lounge and four dining islands occupy the daylight zone.
  const item = (key, x, z, rotationY = 0, tag = "") => ({ key, x, z, rotationY, tag });
  const groups = [
    { name: "reception", x: -6, z: -4.5, hx: -6, hz: -4.5, members: [
      item("reception", 0, 0, 0, "reception"),
      item("cabinet", 0, -1.65, 0, "cabinet")
    ] },
    { name: "bar", x: 6, z: -4.4, hx: 6, hz: -4.4, members: [
      item("bar", 0, 0, 0, "bar"),
      item("barback", 0, -1.65),
      item("stool", -1.55, 1.02, Math.PI),
      item("stool", 0, 1.02, Math.PI),
      item("stool", 1.55, 1.02, Math.PI)
    ] },
    { name: "lounge", x: -6, z: 0.7, hx: -6, hz: 0.7, members: [
      item("sofa", 0, 1.65, Math.PI),
      item("coffee", 0, 0, 0, "coffee"),
      item("lounge", -2.65, -0.15, Math.PI / 2),
      item("lounge", 2.65, -0.15, -Math.PI / 2),
      item("side", -2.35, 1.7, 0, "side"),
      item("floorlamp", 2.55, 1.9)
    ] }
  ];
  for (const x of [4.05, 8.15]) for (const z of [0.25, 4.25]) {
    groups.push({
      name: "dining", x, z, hx: x, hz: z,
      members: [
        item("table", 0, 0, 0, "table"),
        item("diningchair", 0, 1.12, Math.PI),
        item("diningchair", 0, -1.12, 0),
        item("diningchair", 1.12, 0, -Math.PI / 2),
        item("diningchair", -1.12, 0, Math.PI / 2)
      ]
    });
  }

  const copy = a => a.map(g => ({ ...g, members: g.members.map(m => ({ ...m })) }));
  function boxes(a) {
    const out = [];
    a.forEach((g, gi) => g.members.forEach(m => {
      const d = dims[m.key], c = Math.abs(Math.cos(m.rotationY)), s = Math.abs(Math.sin(m.rotationY));
      out.push({ x: g.x + m.x, z: g.z + m.z, w: d[0] * c + d[2] * s, d: d[2] * c + d[0] * s, gi });
    }));
    return out;
  }
  function overlap(a, b, gap) {
    const dx = (a.w + b.w) / 2 + gap - Math.abs(a.x - b.x);
    const dz = (a.d + b.d) / 2 + gap - Math.abs(a.z - b.z);
    return dx > 0 && dz > 0 ? dx * dz : 0;
  }
  const swingZones = entrances.map(o => {
    const w = Math.max(2, o.width || 2.4), t = o.offset || 0;
    if (o.wall === "north") return { x: t, z: -6.85, w: w + 0.6, d: 2.3 };
    if (o.wall === "south") return { x: t, z: 6.85, w: w + 0.6, d: 2.3 };
    if (o.wall === "west") return { x: -10.85, z: t, w: 2.3, d: w + 0.6 };
    return { x: 10.85, z: t, w: 2.3, d: w + 0.6 };
  });
  function clearanceKept(bs) {
    let p = 0;
    for (const b of bs) {
      // Central procession spine and continuous perimeter circulation.
      p += overlap(b, { x: 0, z: 0, w: 2.6, d: 16 }, 0) * 1500;
      p += Math.max(0, Math.abs(b.x) + b.w / 2 - 10.45) ** 2 * 2000;
      p += Math.max(0, Math.abs(b.z) + b.d / 2 - 6.45) ** 2 * 2000;
      for (const zone of swingZones) p += overlap(b, zone, 0.1) * 2000;
    }
    return p;
  }
  function nothingColliding(bs) {
    let p = 0;
    for (let i = 0; i < bs.length; i++) for (let j = i + 1; j < bs.length; j++) {
      p += overlap(bs[i], bs[j], bs[i].gi === bs[j].gi ? 0.05 : 0.8) * 1800;
    }
    return p;
  }
  function pairDistances(a) {
    // Rigid subgrammars preserve chair/table distances and staff work aisles.
    return a.reduce((p, g) => p + 2 * ((g.x - g.hx) ** 2 + (g.z - g.hz) ** 2), 0);
  }
  function focalView(a) {
    const r = a[0], l = a[2];
    return 9 * (r.x - l.x) ** 2 + 0.3 * (r.z + 4.5) ** 2;
  }
  const score = a => {
    const bs = boxes(a);
    return clearanceKept(bs) + nothingColliding(bs) + pairDistances(a) + focalView(a);
  };
  function repair(a) {
    for (let pass = 0; pass < 5; pass++) {
      for (let k = 0; k < a.length; k++) {
        const g = a[k];
        const options = [[0, 0], [0.22, 0], [-0.22, 0], [0, 0.22], [0, -0.22]];
        let best = score(a), bx = g.x, bz = g.z;
        const ox = g.x, oz = g.z;
        for (const [dx, dz] of options) {
          g.x = ox + dx; g.z = oz + dz;
          const value = score(a);
          if (value < best) { best = value; bx = g.x; bz = g.z; }
        }
        g.x = bx; g.z = bz;
      }
    }
  }
  let current = copy(groups);
  repair(current);
  let kept = copy(current), keptScore = score(kept), currentScore = keptScore;
  for (let step = 0; step < 380; step++) {
    const candidate = copy(current);
    const index = Math.floor(Math.random() * candidate.length);
    const g = candidate[index];
    const temp = 0.8 * (1 - step / 380) + 0.015;
    g.x += (Math.random() - 0.5) * temp;
    g.z += (Math.random() - 0.5) * temp;
    if (step % 40 === 0) repair(candidate);
    const value = score(candidate);
    if (value < currentScore || Math.random() < Math.exp((currentScore - value) / temp)) {
      current = candidate; currentScore = value;
    }
    if (value < keptScore) { kept = copy(candidate); keptScore = value; }
  }
  repair(kept);

  // Bounded drop-and-replace repair selects a new location for the worst group.
  for (let pass = 0; pass < 2; pass++) {
    const full = score(kept);
    let worst = -1, largest = 0;
    for (let i = 0; i < kept.length; i++) {
      const bs = boxes(kept).filter(b => b.gi === i);
      const burden = clearanceKept(bs);
      if (burden > largest) { largest = burden; worst = i; }
    }
    if (worst < 0) break;
    let replacement = copy(kept), value = full;
    for (let j = 0; j < 60; j++) {
      const trial = copy(kept), g = trial[worst];
      g.x = g.hx + (Math.random() - 0.5) * 3;
      g.z = g.hz + (Math.random() - 0.5) * 2.2;
      const s = score(trial);
      if (s < value) { value = s; replacement = trial; }
    }
    kept = replacement;
    repair(kept);
  }

  const ids = {};
  function floor(key, x, z, rotationY = 0, dimensions) {
    return api.place({
      assetId: api.asset(key), position: api.roomPoint(x, z, 0),
      rotationY, dimensions: dimensions || dims[key],
      role: key === "rug" ? "decor" : "functional"
    });
  }
  function support(key, parentId, offset = [0, 0]) {
    return api.attach({ assetId: api.asset(key), parentId, kind: "supported", offset, dimensions: dims[key], role: "decor" });
  }
  const lounge = kept[2];
  floor("rug", lounge.x, lounge.z + 0.6);
  for (const g of kept) {
    for (const m of g.members) {
      const id = floor(m.key, g.x + m.x, g.z + m.z, m.rotationY);
      if (m.tag && m.tag !== "table") ids[m.tag] = id;
      if (m.tag === "table") {
        support("vase", id);
        api.place({ assetId: api.asset("pendant"), position: api.ceilingPoint(g.x, g.z, 0.48, 0.65), dimensions: dims.pendant, role: "functional" });
      }
    }
  }
  support("books", ids.coffee, [-0.55, 0]);
  support("tray", ids.coffee, [0.4, 0]);
  support("vase", ids.reception, [-1.75, 0]);
  support("espresso", ids.bar, [1.2, -0.05]);
  support("tray", ids.bar, [-1.25, 0]);
  support("vase", ids.side);

  const occupied = boxes(kept);
  for (const [x, z] of [[-9.5, -4.5], [-9.5, 4.8], [-3, 4.8], [9.6, -4.5]]) {
    const b = { x, z, w: 0.85, d: 0.85 };
    if (clearanceKept([b]) === 0 && occupied.every(o => !overlap(b, o, 0.45))) {
      floor("plant", x, z); occupied.push(b);
    }
  }
  function wallDecor(key, wall, offset, bottom) {
    const f = api.wallFrame(wall, offset, bottom, 0.06);
    api.place({ assetId: api.asset(key), position: f.point, facing: { direction: f.inward }, dimensions: dims[key], role: "decor" });
  }
  function clearWall(wall, center, width) {
    return !existing.concat(entrances).some(o => o.wall === wall && Math.abs((o.offset || 0) - center) < ((o.width || 2.4) + width) / 2 + 0.15);
  }
  for (const [key, preferred, height] of [["emblem", kept[0].x, 2.05], ["art", -6, 1.7]]) {
    const choices = key === "emblem"
      ? [["north", preferred], ["north", -8], ["west", -3], ["east", 3]]
      : [["west", 0.5], ["north", -6], ["east", 0.5], ["north", 8]];
    let chosen = choices.find(([wall, offset]) => clearWall(wall, offset, dims[key][0]));
    if (!chosen) chosen = choices[0];
    wallDecor(key, chosen[0], chosen[1], height);
  }
  for (const [x, z] of [[0, 5.5], [0, 0], [0, -5.5], [-6, -4.5], [6, -4.5], [-6, 0.7], [-6, 5.4]]) {
    api.place({ assetId: api.asset("ceiling"), position: api.ceilingPoint(x, z, 0.16, 0), dimensions: dims.ceiling, role: "functional" });
  }
}

